int
fcb_getnext_nolock(struct fcb *fcb, struct fcb_entry *loc)
{
	int rc;
	struct flash_sector *start_sector;

	if (loc->fe_sector == NULL) {
		loc->fe_sector = fcb->f_oldest;
		loc->fe_elem_off = fcb_len_in_flash(fcb, sizeof(struct fcb_disk_area));
	} else if (loc->fe_elem_off == 0U) {
		/* If offset is zero, we serve the first entry from the sector. */
		loc->fe_elem_off = fcb_len_in_flash(fcb, sizeof(struct fcb_disk_area));
	} else {
		/* Advance to the next element in the current sector */
		loc->fe_elem_off = loc->fe_data_off +
				  fcb_len_in_flash(fcb, loc->fe_data_len) +
				  fcb_len_in_flash(fcb, FCB_CRC_SZ);
	}

	start_sector = loc->fe_sector;

	do {
		rc = fcb_elem_info(fcb, loc);
		if (rc == 0) {
			return 0; /* Found a valid entry */
		} else if (rc == -ENOTSUP) {
			/* End of current sector, move to the next one */
			if (loc->fe_sector == fcb->f_active.fe_sector) {
				/* Reached the active sector and exhausted it, no more entries */
				return -ENOTSUP;
			}
			loc->fe_sector = fcb_getnext_sector(fcb, loc->fe_sector);
			loc->fe_elem_off = fcb_len_in_flash(fcb, sizeof(struct fcb_disk_area));
		} else if (rc == -EBADMSG) {
			/* Corrupt entry, advance past it and try again in the same sector */
			loc->fe_elem_off = loc->fe_data_off +
					  fcb_len_in_flash(fcb, loc->fe_data_len) +
					  fcb_len_in_flash(fcb, FCB_CRC_SZ);
		} else {
			/* Other error, propagate it */
			return rc;
		}
	} while (loc->fe_sector != start_sector || rc == -EBADMSG);

	/* If we exit the loop, it means we've traversed all sectors and found no valid entries,
	 * or we hit an unrecoverable error.
	 * The only way to exit the loop without returning is if `loc->fe_sector == start_sector`
	 * and `rc != -EBADMSG`. This implies `rc` must have been `-ENOTSUP` for the last sector.
	 */
	return -ENOTSUP;
}
